#include <stdio.h>
typedef struct {
    int weight, parent, lchild, rchild;
} HTNode;
HTNode HT[40];    /* 全局数组，成员初值都是 0 */

/* 在 HT[1..k] 中找没有双亲、权值最小的结点 */
int Min(int k, int skip)
{
    int i, m = 0;
    for (i = 1; i <= k; i++) {
        if (HT[i].parent != 0 || i == skip)
            continue;
        if (m == 0 || HT[i].weight < HT[m].weight)
            m = i;
    }
    return m;
}

int main(void)
{
    int n, i, k, s1, s2, w, wpl = 0;
    scanf("%d", &n);
    for (i = 1; i <= n; i++)
        scanf("%d", &HT[i].weight);
    for (k = n + 1; k < 2 * n; k++) {
        s1 = Min(k - 1, 0);
        s2 = Min(k - 1, s1);
        w = HT[s1].weight + HT[s2].weight;
        HT[k].weight = w;
        HT[k].lchild = s1;
        HT[k].rchild = s2;
        HT[s1].parent = HT[s2].parent = k;
        wpl += w;
        printf("%d %d %d\n", w, s1, s2);
    }
    printf("%d\n", wpl);
    return 0;
}
